import{_ as e,o as r,c as s,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-03-11","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-03-11","date":"2021-03-11T00:00:00.000Z","updated":"2021-03-30T00:00:00.000Z","tags":["Ceph","分布式存储","Orchestrator","多站点配置","用户界面设计"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-03-11.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-03-11.md","lastUpdated":1780460162000}'),i={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-03-11.md"};function p(l,t,n,a,_,g){return r(),s("div",null,[...t[0]||(t[0]=[o("<p>Ceph Orchestrator Meeting 2021-03-11 纪要主要讨论了Ceph多站点配置的设置和管理，包括技术实现、用户体验、文档支持和网络配置等方面。</p><p><strong>主要议题包括</strong>：</p><ol><li><p><strong>用户体验</strong>：讨论了多站点配置的设置方式，如YAML文件、CLI命令和GUI向导，决定对新用户和新的集群使用CLI命令设置领域和区域配置，再部署集群。</p></li><li><p><strong>技术实现和测试</strong>：确定使用YAML规范进行QA测试和CI测试的重要性，并讨论了与Rook的兼容性问题。</p></li><li><p><strong>文档和Ansible支持</strong>：强调了确保文档准确性和完整性的重要性，并讨论了Ansible部署和管理多站点配置的问题。</p></li><li><p><strong>网络配置和端口管理</strong>：讨论了网络配置的复杂性，确认这些功能仍在开发中。</p></li><li><p><strong>NFS版本3的支持</strong>：讨论了是否支持NFS版本3，决定通过邮件列表征求社区意见。</p></li></ol><p><strong>决定事项</strong>：</p><ul><li>推荐使用CLI命令设置多站点配置。</li><li>使用YAML规范进行QA测试和CI。</li><li>确保文档准确性和完整性。</li><li>考虑是否完全移除对NFS版本3的支持。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Daniel将测试使用CLI命令部署多站点集群。</li><li>继续开发网络配置和端口管理功能。</li><li>通过邮件列表征求社区意见，决定是否移除对NFS版本3的支持。</li></ul><p>会议还讨论了服务收集和共置的问题，以及如何处理不同服务类型之间的资源平衡。</p>",8)])])}const d=e(i,[["render",p]]);export{h as __pageData,d as default};
